def number_existing_receipts(apps, schema_editor):
    """Money already in the ledger gets its receipt number now, so a
    receipt can be issued for a payment recorded before this existed.
    Oldest first, so the numbers run in the order the money arrived."""
    Payment = apps.get_model("psa", "Payment")
    rows = Payment.objects.filter(amount__gt=0, receipt_number__isnull=True).order_by("pk")
    for row in rows:
        row.receipt_number = f"MSR-{row.recorded_at.year}-{row.pk:05d}"
    Payment.objects.bulk_update(rows, ["receipt_number"])


def unnumber(apps, schema_editor):
    apps.get_model("psa", "Payment").objects.update(receipt_number=None)


